-- Development-only in-game harness; host tests omit the engine predicate.
if type(isDebugEnabled)=="function" and isDebugEnabled()~=true then return {} end

local B47ANCEDPower=require "B47ANCEDPower/Definitions"
local Harness={}
local FILE="theWorks Test Results - B47ANCEDPower.txt"
local KEY="B47ANCEDPower.TestSession.V1"
local TOKEN=tostring({})
local steps={
 {id="startup",feature="Canonical standalone load, definitions, and result export",instruction="Run B47ANCEDPowerTestAuto()."},
 {id="kit",feature="Deterministic watch and coin-cell kit",instruction="Run B47ANCEDPowerTestKit()."},
 {id="watch_service",feature="Digital-watch remove, install, and replacement",instruction="Use the watch battery menu; confirm timed actions, charge, and exactly one cell per operation."},
 {id="watch_boundaries",feature="Mechanical and solar watch boundaries",instruction="Confirm a classic watch has no battery action and a solar military watch needs no battery."},
 {id="cell_compatibility",feature="Cell size, empty-cell, and occupied-device rules",instruction="Try wrong, empty, occupied, nested, and equipped cases; confirm they fail without item or energy loss."},
 {id="crafting",feature="Improvised AA and taped-pack energy conservation",instruction="Craft the prompted adapter and packs from partly charged cells; confirm the expected output and fit."},
 {id="persistence",feature="Charge and installed state save/reload persistence",instruction="Save/quit/reload after servicing the test watch, then run B47ANCEDPowerTestReload()."},
 {id="sandbox",feature="Portable-power settings",instruction="Run B47ANCEDPowerTestSandbox() and follow the setting-change instructions."},
 {id="multiplayer",feature="Hosted and dedicated authority",instruction="Verify nested/equipped service, one mutation, synchronized charge, reconnect, and late join; BLOCKED until available."},
}
local function safe(v)return tostring(v or""):gsub("[\r\n]+"," "):sub(1,500)end
local function now()local lib=rawget(_G,"os");if type(lib)=="table"and type(lib.date)=="function"then local ok,v=pcall(lib.date,"!%Y-%m-%dT%H:%M:%SZ");if ok and v then return tostring(v)end end;return"timestamp unavailable"end
local function player()local f=rawget(_G,"getSpecificPlayer");if type(f)=="function"then local ok,v=pcall(f,0);if ok and v then return v end end;f=rawget(_G,"getPlayer");if type(f)=="function"then local ok,v=pcall(f);if ok then return v end end end
local function data(v)if not v or type(v.getModData)~="function"then return nil end;local ok,d=pcall(v.getModData,v);return ok and type(d)=="table"and d or nil end
local function version()local f=rawget(_G,"getCore");if type(f)~="function"then return"unavailable"end;local ok,c=pcall(f);if ok and c then for _,n in ipairs({"getVersionNumber","getVersion"})do if type(c[n])=="function"then local read,v=pcall(c[n],c);if read and v~=nil then return tostring(v)end end end end;return"unavailable"end
local function session(create)local p=player();local d=data(p);if not d then return nil,nil,"local player ModData unavailable"end;if create and type(d[KEY])~="table"then d[KEY]={schemaVersion=1,sessionId="POWER-"..safe(now()),startedAt=now(),pzVersion=version(),modVersion=B47ANCEDPower.VERSION,runtimeToken=TOKEN,results={},commands={}}end;return d[KEY],p end
local function counts(s)local c={PASS=0,FAIL=0,BLOCKED=0,PENDING=0};for _,step in ipairs(steps)do local status=s.results[step.id]and s.results[step.id].status or"PENDING";c[status]=(c[status]or 0)+1 end;return c end
local function overall(s)local c=counts(s);if c.FAIL>0 then return"FAIL"elseif c.PENDING>0 then return"IN_PROGRESS"elseif c.BLOCKED>0 then return"BLOCKED"end;return"PASS"end
local function lines(s)local out={"theWorks in-game test results","Mod: B47ANCE'd Power","Mod ID: B47ANCEDPower","Mod version: "..safe(s.modVersion),"Project Zomboid version: "..safe(s.pzVersion),"Session: "..safe(s.sessionId),"Started: "..safe(s.startedAt),"Generated: "..now(),"Dependencies enabled for this stage: none (prior Nightfall stages remain separately gated)","Overall session status: "..overall(s),"","FEATURE RESULTS"};for i,step in ipairs(steps)do local r=s.results[step.id]or{status="PENDING",note=""};out[#out+1]=string.format("%02d. [%s] %s | %s | %s",i,r.status,step.id,step.feature,safe(r.note))end;out[#out+1]="";out[#out+1]="COMMAND LOG";for i,e in ipairs(s.commands)do out[#out+1]=string.format("%03d. %s | %s | %s | %s | %s",i,safe(e.at),safe(e.command),safe(e.feature),safe(e.outcome),safe(e.detail))end;return out end
local function writeReport(s)local f=rawget(_G,"getFileWriter");if type(f)~="function"then return false,"getFileWriter unavailable"end;local ok,err=pcall(function()local w=f(FILE,true,false);if not w then error("writer unavailable")end;for _,line in ipairs(lines(s))do if type(w.writeln)=="function"then w:writeln(line)else w:write(line.."\n")end end;if type(w.close)=="function"then w:close()end end);return ok,ok and nil or safe(err)end
local function say(v)print("[B47ANCE'd Power][Test] "..v)end
local function record(s,id,status,note)s.results[id]={status=status,note=safe(note),recordedAt=now()}end
local function finish(s,command,feature,status,detail)s.commands[#s.commands+1]={at=now(),command=command,feature=feature,outcome=status,detail=safe(detail)};while #s.commands>128 do table.remove(s.commands,1)end;local saved,err=writeReport(s);say(command..": "..status.." "..safe(detail));say(saved and("Results saved to Zomboid/Lua/"..FILE)or("Result export failed: "..safe(err)));return status=="PASS",detail end
local function pending(s)for _,step in ipairs(steps)do if not s.results[step.id]then return step end end end
local function items(inventory)local out={};if not inventory or type(inventory.getItems)~="function"then return out end;local ok,list=pcall(inventory.getItems,inventory);if not ok or not list then return out end;if type(list.size)=="function"and type(list.get)=="function"then local sizeOk,n=pcall(list.size,list);if sizeOk then for i=0,math.min(tonumber(n)or 0,512)-1 do local read,item=pcall(list.get,list,i);if read then out[#out+1]=item end end end elseif type(list)=="table"then for _,item in ipairs(list)do out[#out+1]=item end end;return out end
local function fullType(item)if not item or type(item.getFullType)~="function"then return nil end;local ok,v=pcall(item.getFullType,item);return ok and tostring(v)or nil end
function Harness.auto()local s,_,err=session(true);if not s then say(err);return false,err end;local canonical=rawget(_G,"B47ANCEDPower")==B47ANCEDPower and B47ANCEDPower.VERSION==s.modVersion;local definitions=B47ANCEDPower.getBatteryProfile("B47ANCEDPower.BatteryCoin")~=nil and B47ANCEDPower.getConsumerProfile("Base.WristWatch_Right_DigitalBlack")~=nil;local surfaces=type(B47ANCEDPower.installBattery)=="function"and type(B47ANCEDPower.getConsumerPowerState)=="function"and type(B47ANCEDPower.beginEnergyTransaction)=="function";local writerOk,writerError=writeReport(s);local pass=canonical and definitions and surfaces and writerOk;local detail=string.format("canonical=%s definitions=%s surfaces=%s writer=%s",tostring(canonical),tostring(definitions),tostring(surfaces),tostring(writerOk));if writerError then detail=detail.." error="..safe(writerError)end;record(s,"startup",pass and"PASS"or"FAIL",detail);return finish(s,"B47ANCEDPowerTestAuto()","startup",pass and"PASS"or"FAIL",detail)end
function Harness.start(reset)local s,p,err=session(true);if not s then say(err);return false,err end;if reset==true then data(p)[KEY]=nil;s=session(true)end;Harness.auto();local step=pending(s);say("Session started. Test B47ANCEDPower alone for this stage.");if step then say("NEXT ["..step.id.."] "..step.instruction)end;return true,s.sessionId end
function Harness.kit()local s,p=session(false);if not B47ANCEDPower.isAuthority or not B47ANCEDPower.isAuthority() then say("Test kit requires an authoritative operator; client spawning is blocked");return false end;if not s then say("No session; run B47ANCEDPowerTestStart(true)");return false end;if type(p.getInventory)~="function"then return finish(s,"B47ANCEDPowerTestKit()","kit","FAIL","player inventory unavailable")end;local inventory=p:getInventory();if not inventory or type(inventory.AddItem)~="function"then return finish(s,"B47ANCEDPowerTestKit()","kit","FAIL","inventory AddItem unavailable")end;local have={};for _,item in ipairs(items(inventory))do have[fullType(item)]=(have[fullType(item)]or 0)+1 end;for _,entry in ipairs({{"Base.WristWatch_Right_DigitalBlack",1},{"B47ANCEDPower.BatteryCoin",2}})do for _=(have[entry[1]]or 0)+1,entry[2]do local added,item=pcall(inventory.AddItem,inventory,entry[1]);if not added or not item then return finish(s,"B47ANCEDPowerTestKit()","kit","FAIL","test item unavailable: "..entry[1])end end end;record(s,"kit","PASS","digital watch and two coin cells available without duplication");say("Right-click the digital watch and use its battery actions. Keep one coin cell for replacement.");return finish(s,"B47ANCEDPowerTestKit()","kit","PASS","watch=1 coinCells=2")end
function Harness.reloadStatus()
    local s=session(false);if not s then say("No session");return false end
    if s.runtimeToken==TOKEN then return finish(s,"B47ANCEDPowerTestReload()","persistence","BLOCKED","save/quit/reload still required") end
    s.reloadObserved=true
    say("Session reload observed. This does not verify battery energy or physical items.")
    say("Compare installed charge and exact item counts; record TestPass with those observations when persistence is the current step.")
    return finish(s,"B47ANCEDPowerTestReload()","persistence","BLOCKED","manual item and energy observations required")
end
function Harness.sandbox()local s=session(false);if not s then say("No session");return false end;local root=rawget(_G,"SandboxVars");local values=root and root.B47ANCEDPower;local value=values and values.EnableImprovisedAdapters;if type(value)~="boolean"then return finish(s,"B47ANCEDPowerTestSandbox()","sandbox","FAIL","B47ANCEDPower setting unavailable")end;if s.sandboxOriginal==nil then s.sandboxOriginal=value;s.sandboxRequested=not value;say("B47ANCE'd Power TEST — Settings");say("Open Sandbox Options > B47ANCE'd Power and set Enable improvised adapters to "..(s.sandboxRequested and"ON"or"OFF")..". Apply it, return, and run B47ANCEDPowerTestSandbox() again.");return finish(s,"B47ANCEDPowerTestSandbox()","sandbox","BLOCKED","waiting for requested setting change")end;if value~=s.sandboxRequested then return finish(s,"B47ANCEDPowerTestSandbox()","sandbox","BLOCKED","setting has not changed yet")end;record(s,"sandbox","PASS","runtime observed the requested setting change");say("Verified. Restore Enable improvised adapters to "..(s.sandboxOriginal and"ON"or"OFF").." after testing.");return finish(s,"B47ANCEDPowerTestSandbox()","sandbox","PASS","original="..tostring(s.sandboxOriginal).." changed="..tostring(value))end
function Harness.recordCurrent(status,note)local s=session(false);if not s then say("No session");return false end;local step=pending(s);if not step then say("All steps recorded");return false end;if step.id=="persistence" and status=="PASS" and (not s.reloadObserved or type(note)~="string" or #note<8) then say("Persistence needs an observed reload and explicit item/energy comparison notes");return false end;record(s,step.id,status,note);finish(s,"B47ANCEDPowerTest"..status:sub(1,1)..status:sub(2):lower().."()",step.id,status,note);local nextStep=pending(s);if nextStep then say("NEXT ["..nextStep.id.."] "..nextStep.instruction)end;return true end
function Harness.report()local s=session(false);if not s then say("No session");return false end;for _,line in ipairs(lines(s))do say(line)end;return writeReport(s)end
function Harness.where()say("Windows result file: %USERPROFILE%\\Zomboid\\Lua\\"..FILE);return FILE end
B47ANCEDPowerTestStart=function(reset)return Harness.start(reset)end;B47ANCEDPowerTestAuto=function()return Harness.auto()end;B47ANCEDPowerTestKit=function()return Harness.kit()end;B47ANCEDPowerTestReload=function()return Harness.reloadStatus()end;B47ANCEDPowerTestSandbox=function()return Harness.sandbox()end;B47ANCEDPowerTestPass=function(note)return Harness.recordCurrent("PASS",note)end;B47ANCEDPowerTestFail=function(note)return Harness.recordCurrent("FAIL",note)end;B47ANCEDPowerTestBlocked=function(note)return Harness.recordCurrent("BLOCKED",note)end;B47ANCEDPowerTestReport=function()return Harness.report()end;B47ANCEDPowerTestWhere=function()return Harness.where()end
B47ANCEDPower.TestHarness=Harness;say("Ready: B47ANCEDPowerTestStart(true); results export to Zomboid/Lua/"..FILE);return Harness
